   210	/* Optimization:
   211	 * json_tokener_parse_ex() consumed a lot of CPU in its main loop,
   212	 * iterating character-by character.  A large performance boost is
   213	 * achieved by using tighter loops to locally handle units such as
   214	 * comments and strings.  Loops that handle an entire token within
   215	 * their scope also gather entire strings and pass them to
   216	 * printbuf_memappend() in a single call, rather than calling
   217	 * printbuf_memappend() one char at a time.
   218	 *
   219	 * PEEK_CHAR() and ADVANCE_CHAR() macros are used for code that is
   220	 * common to both the main loop and the tighter loops.
   221	 */
   222	
   223	/* PEEK_CHAR(dest, tok) macro:
   224	 *   Peeks at the current char and stores it in dest.
   225	 *   Returns 1 on success, sets tok->err and returns 0 if no more chars.
   226	 *   Implicit inputs:  str, len vars
   227	 */
   228	#define PEEK_CHAR(dest, tok)                                                 \
   229	        (((tok)->char_offset == len)                                         \
   230	             ? (((tok)->depth == 0 && state == json_tokener_state_eatws &&   \
   231	                 saved_state == json_tokener_state_finish)                   \
   232	                    ? (((tok)->err = json_tokener_success), 0)               \
   233	                    : (((tok)->err = json_tokener_continue), 0))             \
   234	             : (((tok->flags & JSON_TOKENER_VALIDATE_UTF8) &&                \
   235	                 (!json_tokener_validate_utf8(*str, nBytesp)))               \
   236	                    ? ((tok->err = json_tokener_error_parse_utf8_string), 0) \
   237	                    : (((dest) = *str), 1)))
   238	
   239	/* ADVANCE_CHAR() macro:
   240	 *   Increments str & tok->char_offset.
   241	 *   For convenience of existing conditionals, returns the old value of c (0 on eof)
   242	 *   Implicit inputs:  c var
   243	 */
   244	#define ADVANCE_CHAR(str, tok) (++(str), ((tok)->char_offset)++, c)
   245	
   246	/* End optimization macro defs */
   247	
   248	struct json_object *json_tokener_parse_ex(struct json_tokener *tok, const char *str, int len)
   249	{
   250	        struct json_object *obj = NULL;
   251	        char c = '\1';
   252	        unsigned int nBytes = 0;
   253	        unsigned int *nBytesp = &nBytes;
   254	
   255	#ifdef HAVE_USELOCALE
   256	        locale_t oldlocale = uselocale(NULL);
   257	        locale_t newloc;
   258	#elif defined(HAVE_SETLOCALE)
   259	        char *oldlocale = NULL;
   260	#endif
   261	
   262	        tok->char_offset = 0;
   263	        tok->err = json_tokener_success;
   264	
   265	        /* this interface is presently not 64-bit clean due to the int len argument
   266	         * and the internal printbuf interface that takes 32-bit int len arguments
   267	         * so the function limits the maximum string size to INT32_MAX (2GB).
   268	         * If the function is called with len == -1 then strlen is called to check
   269	         * the string length is less than INT32_MAX (2GB)
   270	         */
   271	        if ((len < -1) || (len == -1 && strlen(str) > INT32_MAX))
   272	        {
   273	                tok->err = json_tokener_error_size;
   274	                return NULL;
   275	        }
   276	
   277	#ifdef HAVE_USELOCALE
   278	        {
   279	                locale_t duploc = duplocale(oldlocale);
   280	                newloc = newlocale(LC_NUMERIC_MASK, "C", duploc);
   281	                if (newloc == NULL)
   282	                {
   283	                        freelocale(duploc);
   284	                        return NULL;
   285	                }
   286	                uselocale(newloc);
   287	        }
   288	#elif defined(HAVE_SETLOCALE)
   289	        {
   290	                char *tmplocale;
   291	                tmplocale = setlocale(LC_NUMERIC, NULL);
   292	                if (tmplocale)
   293	                        oldlocale = strdup(tmplocale);
   294	                setlocale(LC_NUMERIC, "C");
   295	        }
   296	#endif
   297	
   298	        while (PEEK_CHAR(c, tok))
   299	        {
   300	
   301	        redo_char:
   302	                switch (state)
   303	                {
   304	
   305	                case json_tokener_state_eatws:
   306	                        /* Advance until we change state */
   307	                        while (isspace((unsigned char)c))
   308	                        {
   309	                                if ((!ADVANCE_CHAR(str, tok)) || (!PEEK_CHAR(c, tok)))
   310	                                        goto out;
   311	                        }
   312	                        if (c == '/' && !(tok->flags & JSON_TOKENER_STRICT))
   313	                        {
   314	                                printbuf_reset(tok->pb);
   315	                                printbuf_memappend_fast(tok->pb, &c, 1);
   316	                                state = json_tokener_state_comment_start;
   317	                        }
   318	                        else
   319	                        {
   320	                                state = saved_state;
   321	                                goto redo_char;
   322	                        }
   323	                        break;
   324	
   325	                case json_tokener_state_start:
   326	                        switch (c)
   327	                        {
   328	                        case '{':
   329	                                state = json_tokener_state_eatws;
   330	                                saved_state = json_tokener_state_object_field_start;
   331	                                current = json_object_new_object();
   332	                                if (current == NULL)
   333	                                        goto out;
   334	                                break;
   335	                        case '[':
   336	                                state = json_tokener_state_eatws;
   337	                                saved_state = json_tokener_state_array;
   338	                                current = json_object_new_array();
   339	                                if (current == NULL)
   340	                                        goto out;
   341	                                break;
   342	                        case 'I':
   343	                        case 'i':
   344	                                state = json_tokener_state_inf;
   345	                                printbuf_reset(tok->pb);
   346	                                tok->st_pos = 0;
   347	                                goto redo_char;
   348	                        case 'N':
   349	                        case 'n':
   350	                                state = json_tokener_state_null; // or NaN
   351	                                printbuf_reset(tok->pb);
   352	                                tok->st_pos = 0;
   353	                                goto redo_char;
   354	                        case '\'':
   355	                                if (tok->flags & JSON_TOKENER_STRICT)
   356	                                {
   357	                                        /* in STRICT mode only double-quote are allowed */
   358	                                        tok->err = json_tokener_error_parse_unexpected;
   359	                                        goto out;
   360	                                }
   361	                                /* FALLTHRU */
   362	                        case '"':
   363	                                state = json_tokener_state_string;
   364	                                printbuf_reset(tok->pb);
   365	                                tok->quote_char = c;
   366	                                break;
   367	                        case 'T':
   368	                        case 't':
   369	                        case 'F':
   370	                        case 'f':
   371	                                state = json_tokener_state_boolean;
   372	                                printbuf_reset(tok->pb);
   373	                                tok->st_pos = 0;
   374	                                goto redo_char;
   375	                        case '0':
   376	                        case '1':
   377	                        case '2':
   378	                        case '3':
   379	                        case '4':
   380	                        case '5':
   381	                        case '6':
   382	                        case '7':
   383	                        case '8':
   384	                        case '9':
   385	                        case '-':
   386	                                state = json_tokener_state_number;
   387	                                printbuf_reset(tok->pb);
   388	                                tok->is_double = 0;
   389	                                goto redo_char;
   390	                        default: tok->err = json_tokener_error_parse_unexpected; goto out;
   391	                        }
   392	                        break;
   393	
   394	                case json_tokener_state_finish:
   395	                        if (tok->depth == 0)
   396	                                goto out;
   397	                        obj = json_object_get(current);
   398	                        json_tokener_reset_level(tok, tok->depth);
   399	                        tok->depth--;
   400	                        goto redo_char;
   401	
   402	                case json_tokener_state_inf: /* aka starts with 'i' (or 'I', or "-i", or "-I") */
   403	                {
   404	                        /* If we were guaranteed to have len set, then we could (usually) handle
   405	                         * the entire "Infinity" check in a single strncmp (strncasecmp), but
   406	                         * since len might be -1 (i.e. "read until \0"), we need to check it
   407	                         * a character at a time.
   408	                         * Trying to handle it both ways would make this code considerably more
   409	                         * complicated with likely little performance benefit.
   410	                         */
   411	                        int is_negative = 0;
   412	                        const char *_json_inf_str = json_inf_str;
   413	                        if (!(tok->flags & JSON_TOKENER_STRICT))
   414	                                _json_inf_str = json_inf_str_lower;
   415	
   416	                        /* Note: tok->st_pos must be 0 when state is set to json_tokener_state_inf */
   417	                        while (tok->st_pos < (int)json_inf_str_len)
   418	                        {
   419	                                char inf_char = *str;
   420	                                if (!(tok->flags & JSON_TOKENER_STRICT))
   421	                                        inf_char = tolower((int)*str);
   422	                                if (inf_char != _json_inf_str[tok->st_pos])
   423	                                {
   424	                                        tok->err = json_tokener_error_parse_unexpected;
   425	                                        goto out;
   426	                                }
   427	                                tok->st_pos++;
   428	                                (void)ADVANCE_CHAR(str, tok);
   429	                                if (!PEEK_CHAR(c, tok))
   430	                                {
   431	                                        /* out of input chars, for now at least */
   432	                                        goto out;
   433	                                }
   434	                        }
   435	                        /* We checked the full length of "Infinity", so create the object.
   436	                         * When handling -Infinity, the number parsing code will have dropped
   437	                         * the "-" into tok->pb for us, so check it now.
   438	                         */
   439	                        if (printbuf_length(tok->pb) > 0 && *(tok->pb->buf) == '-')
   440	                        {
   441	                                is_negative = 1;
   442	                        }
   443	                        current = json_object_new_double(is_negative ? -INFINITY : INFINITY);
   444	                        if (current == NULL)
   445	                                goto out;
   446	                        saved_state = json_tokener_state_finish;
   447	                        state = json_tokener_state_eatws;
   448	                        goto redo_char;
   449	                }
   450	                break;
   451	                case json_tokener_state_null: /* aka starts with 'n' */
   452	                {
   453	                        int size;
   454	                        int size_nan;
   455	                        printbuf_memappend_fast(tok->pb, &c, 1);
   456	                        size = json_min(tok->st_pos + 1, json_null_str_len);
   457	                        size_nan = json_min(tok->st_pos + 1, json_nan_str_len);
   458	                        if ((!(tok->flags & JSON_TOKENER_STRICT) &&
   459	                             strncasecmp(json_null_str, tok->pb->buf, size) == 0) ||
   460	                            (strncmp(json_null_str, tok->pb->buf, size) == 0))
   461	                        {
   462	                                if (tok->st_pos == json_null_str_len)
   463	                                {
   464	                                        current = NULL;
   465	                                        saved_state = json_tokener_state_finish;
   466	                                        state = json_tokener_state_eatws;
   467	                                        goto redo_char;
   468	                                }
   469	                        }
   470	                        else if ((!(tok->flags & JSON_TOKENER_STRICT) &&
   471	                                  strncasecmp(json_nan_str, tok->pb->buf, size_nan) == 0) ||
   472	                                 (strncmp(json_nan_str, tok->pb->buf, size_nan) == 0))
   473	                        {
   474	                                if (tok->st_pos == json_nan_str_len)
   475	                                {
   476	                                        current = json_object_new_double(NAN);
   477	                                        if (current == NULL)
   478	                                                goto out;
   479	                                        saved_state = json_tokener_state_finish;
   480	                                        state = json_tokener_state_eatws;
   481	                                        goto redo_char;
   482	                                }
   483	                        }
   484	                        else
   485	                        {
   486	                                tok->err = json_tokener_error_parse_null;
   487	                                goto out;
   488	                        }
   489	                        tok->st_pos++;
   490	                }
   491	                break;
   492	
   493	                case json_tokener_state_comment_start:
   494	                        if (c == '*')
   495	                        {
   496	                                state = json_tokener_state_comment;
   497	                        }
   498	                        else if (c == '/')
   499	                        {
   500	                                state = json_tokener_state_comment_eol;
   501	                        }
   502	                        else
   503	                        {
   504	                                tok->err = json_tokener_error_parse_comment;
   505	                                goto out;
   506	                        }
   507	                        printbuf_memappend_fast(tok->pb, &c, 1);
   508	                        break;
   509	
   510	                case json_tokener_state_comment:
   511	                {
   512	                        /* Advance until we change state */
   513	                        const char *case_start = str;
   514	                        while (c != '*')
   515	                        {
   516	                                if (!ADVANCE_CHAR(str, tok) || !PEEK_CHAR(c, tok))
   517	                                {
   518	                                        printbuf_memappend_fast(tok->pb, case_start,
   519	                                                                str - case_start);
   520	                                        goto out;
   521	                                }
   522	                        }
   523	                        printbuf_memappend_fast(tok->pb, case_start, 1 + str - case_start);
   524	                        state = json_tokener_state_comment_end;
   525	                }
   526	                break;
   527	
   528	                case json_tokener_state_comment_eol:
   529	                {
   530	                        /* Advance until we change state */
   531	                        const char *case_start = str;
   532	                        while (c != '\n')
   533	                        {
   534	                                if (!ADVANCE_CHAR(str, tok) || !PEEK_CHAR(c, tok))
   535	                                {
   536	                                        printbuf_memappend_fast(tok->pb, case_start,
   537	                                                                str - case_start);
   538	                                        goto out;
   539	                                }
   540	                        }
   541	                        printbuf_memappend_fast(tok->pb, case_start, str - case_start);
   542	                        MC_DEBUG("json_tokener_comment: %s\n", tok->pb->buf);
   543	                        state = json_tokener_state_eatws;
   544	                }
   545	                break;
   546	
   547	                case json_tokener_state_comment_end:
   548	                        printbuf_memappend_fast(tok->pb, &c, 1);
   549	                        if (c == '/')
   550	                        {
   551	                                MC_DEBUG("json_tokener_comment: %s\n", tok->pb->buf);
   552	                                state = json_tokener_state_eatws;
   553	                        }
   554	                        else
   555	                        {
   556	                                state = json_tokener_state_comment;
   557	                        }
   558	                        break;
   559	
   560	                case json_tokener_state_string:
   561	                {
   562	                        /* Advance until we change state */
   563	                        const char *case_start = str;
   564	                        while (1)
   565	                        {
   566	                                if (c == tok->quote_char)
   567	                                {
   568	                                        printbuf_memappend_fast(tok->pb, case_start,
   569	                                                                str - case_start);
   570	                                        current =
   571	                                            json_object_new_string_len(tok->pb->buf, tok->pb->bpos);
   572	                                        if (current == NULL)
